if(!UnityEditor.EditorApplication.isPlaying||BackpackUIManager.Instance==null)throw new System.Exception("Initialized Play Mode required");
var rows=new System.Collections.Generic.List<object>();
System.Action<string,bool> check=(name,ok)=>rows.Add(new{test=name,passed=ok});
var ui=UnityEngine.Object.FindObjectOfType<UİManager>();
var bags=BackpackUIManager.Instance;var shop=UnityEngine.Object.FindObjectOfType<ShopUIManager>(true);
var t=UnityEngine.Object.FindObjectOfType<ArcherTower>();
var fire=Resources.Load<ItemData>("Data/Items/Elements/Fire");
UİManager.activeTower=t;bags.OpenBackpack(t);shop.UpdateShopUI();
var root=(RectTransform)bags.combinedPanel.transform;
check("old panel dimensions 1600 x 930",Mathf.Abs(root.rect.width*root.localScale.x-1600)<1&&Mathf.Abs(root.rect.height*root.localScale.y-930)<1);
check("element selection removed",ui.elementButtons.All(x=>!x.gameObject.activeSelf)&&root.Find("ElementRowCover")!=null);
bool early=true;for(int i=0;i<30;i++){t.GenerateShopItems();early&=t.myShopItems.All(x=>x==null||!x.isElementCatalyst);}
check("no element offers before level five",early);
while(t.Level<4)t.AddExperience(t.ExperienceRequired);
var main=t.Backpack.Items.First(x=>t.IsMainItem(x.Data));
Vector2Int adjacent=Vector2Int.zero;
for(int y=0;y<t.Backpack.Height;y++)for(int x=0;x<t.Backpack.Width;x++)
{var p=new Vector2Int(x,y);if(t.Backpack.CanPlace(fire,p)&&TowerItemEvolution.Adjacent(main,new PlacedItem(fire,p)))adjacent=p;}
var ingredient=t.Backpack.Place(fire,adjacent);t.CalculateStats();
check("level four cannot fuse elements",t.SelectedElement==ElementType.Normal&&t.Backpack.Contains(ingredient));
t.Backpack.Remove(ingredient);
t.AddExperience(t.ExperienceRequired);
check("level five unlocks element shop items",t.Level==5&&t.myShopItems.Any(x=>x!=null&&x.isElementCatalyst));
t.AddExperience(t.ExperienceRequired);check("XP continues past five without element selection",t.Level==6);
t.myShopItems[0]=fire;shop.UpdateShopUI();
var right=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){button=UnityEngine.EventSystems.PointerEventData.InputButton.Right};
shop.shopSlots[0].OnPointerClick(right);check("right click reserves only that offer",t.IsOfferReserved(0)&&!t.IsOfferReserved(1));
int gold=EconomyManager.Gold;shop.rerollButton.onClick.Invoke();
check("paid reroll preserves reservation and charges once",t.myShopItems[0]==fire&&t.IsOfferReserved(0)&&EconomyManager.Gold==gold-shop.rerollCost);
shop.RefreshShopsForPreparation();check("next-wave refresh preserves reserved item",t.myShopItems[0]==fire&&t.IsOfferReserved(0)&&t.myShopItems[3]!=null);
shop.shopSlots[0].OnPointerClick(right);check("second right click removes reservation",!t.IsOfferReserved(0));
var distant=t.Backpack.Place(fire,Vector2Int.zero);t.CalculateStats();
check("nonadjacent catalyst does not transform weapon",t.Backpack.Contains(distant)&&t.SelectedElement==ElementType.Normal);
t.Backpack.Remove(distant);ingredient=t.Backpack.Place(fire,adjacent);gold=EconomyManager.Gold;t.CalculateStats();
check("adjacent fireball becomes fire bow exactly once",t.SelectedElement==ElementType.Fire&&t.Backpack.Items.Any(x=>x.Data==t.data.fireWeapon)&&!t.Backpack.Contains(ingredient)&&EconomyManager.Gold==gold);
check("old selection API cannot bypass catalyst consumption",!t.TrySelectElement(ElementType.Water)&&!t.TryChangeElement(ElementType.Water));
var bullet=UnityEngine.Object.Instantiate(t.ArcherBulletP).GetComponent<Bullet>();bullet.Initialize(null,10,0,t);
var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
check("fire bow projectiles deal fire damage",(ElementType)typeof(Bullet).GetField("damageElement",flags).GetValue(bullet)==ElementType.Fire);UnityEngine.Object.Destroy(bullet.gameObject);
var equipped=t.Backpack.Items.ToArray();bags.MoveAllToStorage();
check("bulk move preserves every item including main weapon",t.Backpack.Items.Count==0&&equipped.All(x=>t.Storage.Contains(x))&&t.SelectedElement==ElementType.Normal);
check("depot has no grid and has physics",t.Storage.IsLooseStorage&&bags.storageGridContainer.GetComponentsInChildren<BackpackCellView>().Length==0&&bags.storageGridContainer.GetComponent<StoragePileUI>()!=null);
main=equipped.First(x=>t.IsMainItem(x.Data));
var drag=bags.storageGridContainer.GetComponentsInChildren<BackpackDraggable>().Last(x=>x.Placed==main);
var ev=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current);
ev.position=RectTransformUtility.WorldToScreenPoint(null,bags.gridContainer.TransformPoint(new Vector3(2.5f*bags.cellSize,-1.5f*bags.cellSize,0)));
drag.BeginDrag();drag.UpdateDrag(ev);bool moved=drag.FinishDrag(ev);
check("main weapon can return from loose depot",moved&&t.Backpack.Contains(main)&&t.SelectedElement==ElementType.Fire);
t.myShopItems[0]=fire;shop.UpdateShopUI();shop.shopSlots[0].OnPointerClick(right);gold=EconomyManager.Gold;
var scroll=bags.storageGridContainer.GetComponentInParent<UnityEngine.UI.ScrollRect>();
ev.position=RectTransformUtility.WorldToScreenPoint(null,scroll.viewport.TransformPoint(scroll.viewport.rect.center));
var starter=shop.shopSlots[0].GetComponent<ShopSlotDragStarter>();starter.OnBeginDrag(ev);starter.OnDrag(ev);starter.OnEndDrag(ev);
check("reserved item can be bought directly into loose depot",EconomyManager.Gold==gold-fire.cost&&t.myShopItems[0]==null&&!t.IsOfferReserved(0)&&t.Storage.Items.Any(x=>x.Data==fire));
int before=t.Storage.Items.Count;for(int i=0;i<25;i++)t.Storage.Place(fire,Vector2Int.zero);bags.RefreshItemVisuals();
check("depot has no old fifteen-cell capacity limit",t.Storage.Items.Count==before+25&&bags.storageGridContainer.rect.height>scroll.viewport.rect.height);
var pile=bags.storageGridContainer.GetComponent<StoragePileUI>();var initial=t.Storage.Items.Select(x=>x.StoragePosition.y).ToArray();
for(int i=0;i<500;i++)pile.Simulate(1f/120f);
check("gravity and collisions settle items into a pile",t.Storage.Items.Where((x,i)=>x.StoragePosition.y>initial[i]+10).Any()&&t.Storage.Items.Select(x=>Mathf.RoundToInt(x.StoragePosition.y/10)).Distinct().Count()>3);
ui.SendMessage("RefreshTowerPanel");bags.GetComponent<TowerPanelLayout>().SendMessage("LateUpdate");
return rows;
